CREATE TABLE IF NOT EXISTS `#__xdecaropeople_people` (`id` int unsigned NOT NULL AUTO_INCREMENT,`uuid` char(36) NOT NULL,`display_name` varchar(255) NOT NULL,`first_name` varchar(150) DEFAULT NULL,`last_name` varchar(150) DEFAULT NULL,`email` varchar(254) DEFAULT NULL,`phone` varchar(50) DEFAULT NULL,`state` tinyint NOT NULL DEFAULT 1,`access` int unsigned NOT NULL DEFAULT 1,`created` datetime NOT NULL,`created_by` int unsigned NOT NULL DEFAULT 0,`modified` datetime DEFAULT NULL,`modified_by` int unsigned NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `idx_uuid` (`uuid`),KEY `idx_name` (`last_name`,`first_name`),KEY `idx_state_access` (`state`,`access`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
